const { chatInput, sessionId } = $('Edit Fields').first().json;

let contextData = {};
let fetchError = false;
try {
  contextData = $('Fetch Owner Context').first().json.context || $('Fetch Owner Context').first().json;
} catch {
  fetchError = true;
}

const alertes = contextData.alerts || [];
const portfolio = contextData.portfolio || {};
const todayItems = contextData.today || [];
const alertsCount = alertes.length;

const systemMessage = `Tu es Kayvibot Owner, l'assistant personnel des propriétaires Kayvila. Tu parles français, tu es proactif, direct et utile.

TON RÔLE
- Analyser les performances du portefeuille du propriétaire
- Alerter sur les actions urgentes (check-in/out du jour, tâches en retard, problèmes OTA)
- Suggérer des optimisations de prix et de disponibilité
- Répondre aux questions sur les réservations, revenus, calendrier

RÈGLES
- Répondre en JSON : { "reply": "...", "action": "reply"|"alert"|"suggestion", "alerts": [...], "suggestedPrompts": [...] }
- Utiliser UNIQUEMENT les données du contexte fourni — ne rien inventer
- Pour les actions sensibles, toujours demander confirmation
- Signaler immédiatement les anomalies

═════════════════════════════
CONTEXTE TEMPS RÉEL :
⚠️ ${alertsCount} alerte(s) active(s)
${JSON.stringify(contextData, null, 2)}
═════════════════════════════`;

return {
  json: {
    chatInput,
    sessionId,
    systemMessage,
    contextData,
    fetchError
  }
};

const aiResponse =
  $input.first().json.output ||
  $input.first().json.message?.content ||
  $input.first().json.text ||
  '';

let reply = aiResponse;
let action = 'reply';
let alerts = [];
let suggestedPrompts = [];

try {
  const parsed = typeof aiResponse === 'string' ? JSON.parse(aiResponse) : aiResponse;
  if (parsed && typeof parsed === 'object') {
    reply = parsed.reply || parsed.response || parsed.message || aiResponse;
    action = parsed.action || 'reply';
    alerts = Array.isArray(parsed.alerts) ? parsed.alerts : [];
    suggestedPrompts = Array.isArray(parsed.suggestedPrompts) ? parsed.suggestedPrompts : [];
  }
} catch {}

return {
  json: { reply, action, alerts, suggestedPrompts }
};
